module freq_divbyfrac(
    input clk, rst_n,
    output clk_div
);
// Parameter definitions
parameter MUL2_DIV_CLK = 7;
// Internal signals
reg [3:0] cnt;
reg clk_div_int;
reg phase_clk;
reg phase_clk_delay;
reg phase_clk_advance;
// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 0;
        clk_div_int <= 0;
        phase_clk <= 0;
        phase_clk_delay <= 0;
        phase_clk_advance <= 0;
    end else begin
        if (cnt == MUL2_DIV_CLK - 1) begin
            cnt <= 0;
        end else begin
            cnt <= cnt + 1;
        end

        if ((cnt >= 0 && cnt <= 3) || (cnt >= 5 && cnt <= 6)) begin
            clk_div_int <= ~clk_div_int;
        end

        if (cnt == 3) begin
            phase_clk <= ~clk_div_int;
        end else if (cnt == 4) begin
            phase_clk_delay <= ~clk_div_int;
        end else if (cnt == 5) begin
            phase_clk_advance <= ~clk_div_int;
        end
    end
end
// Output assignment
assign clk_div = clk_div_int | phase_clk | phase_clk_delay | phase_clk_advance;
endmodule
